<?php require_once __DIR__.'/../config/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{db()->beginTransaction();$s=db()->prepare("SELECT * FROM emprestimos WHERE id=? AND status='ativo' FOR UPDATE");$s->execute([(int)$_POST['id']]);$l=$s->fetch();if(!$l)throw new RuntimeException('Empréstimo não encontrado ou já devolvido.');db()->prepare("UPDATE emprestimos SET status='devolvido',data_devolucao=CURDATE() WHERE id=?")->execute([$l['id']]);db()->prepare('UPDATE livros SET quantidade_disponivel=quantidade_disponivel+1 WHERE id=?')->execute([$l['livro_id']]);db()->commit();flash('success','Livro devolvido com sucesso.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('admin/devolucoes.php');}$loans=db()->query("SELECT e.*,u.nome aluno,l.titulo FROM emprestimos e JOIN usuarios u ON u.id=e.usuario_id JOIN livros l ON l.id=e.livro_id WHERE e.status='ativo' ORDER BY e.data_prevista_devolucao")->fetchAll();$pageTitle='Devoluções';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Livro</th><th>Previsão</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($loans as $l):$late=loan_status($l)==='atrasado'?><tr><td><?=e($l['aluno'])?></td><td><?=e($l['titulo'])?></td><td><?=date('d/m/Y',strtotime($l['data_prevista_devolucao']))?></td><td><span class="badge <?=$late?'off':''?>"><?=$late?'Atrasado':'Ativo'?></span></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn btn-small" data-confirm="Confirmar devolução deste livro?">Registrar devolução</button></form></td></tr><?php endforeach;?><?php if(!$loans):?><tr><td colspan="5" class="empty">Não há devoluções pendentes.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
